// export-controls-component.ts
import { h as h3, inject as inject3 } from "vue";
import {
  CLASS_CONTROLS,
  CLASS_EXPORT_CONTROLS,
  ELEMENT_DIV as ELEMENT_DIV4,
  ImageExportUI,
  SvgExportUI,
  TYPE_JPG,
  TYPE_PNG,
  TYPE_SVG
} from "@visuallyjs/browser-ui";
var ExportControlsComponent = {
  name: COMPONENT_EXPORT_CONTROLS,
  setup(props) {
    return { service: inject3(VisuallyJsServiceKey) };
  },
  props: {
    surfaceId: {
      type: String
    },
    showLabel: {
      type: Boolean,
      default: true
    },
    label: {
      type: String,
      default: "Export :"
    },
    margins: {
      type: Object
    },
    /**
     * Options for SVG exports.
     */
    svgOptions: {
      type: Object
    },
    /**
     * Options for image exports.
     */
    imageOptions: {
      type: Object
    },
    /**
     * Defaults to true.
     */
    allowSvgExport: {
      type: Boolean,
      default: true
    },
    /**
     * Defaults to true.
     */
    allowPngExport: {
      type: Boolean,
      default: true
    },
    /**
     * Defaults to true.
     */
    allowJpgExport: {
      type: Boolean,
      default: true
    }
  },
  methods: {
    loadSurface: function(cb) {
      const s = this.service.surface.value;
      if (s) {
        cb(s);
      }
    },
    exportSVG: function() {
      this.loadSurface((s) => {
        const svgOpts = this.svgOptions || {};
        if (this.margins != null && svgOpts.margins == null) {
          Object.assign(svgOpts, this.margins);
        }
        const svgExporter = new SvgExportUI(s);
        svgExporter.export(svgOpts);
      });
    },
    exportJPG: function() {
      this.loadSurface((s) => {
        const jpgOpts = this.imageOptions || {};
        if (this.margins != null && jpgOpts.margins == null) {
          Object.assign(jpgOpts, this.margins);
        }
        jpgOpts.type = "image/jpeg";
        const jpgExporter = new ImageExportUI(s);
        jpgExporter.export(jpgOpts);
      });
    },
    exportPNG: function() {
      this.loadSurface((s) => {
        const pngOpts = this.imageOptions || {};
        if (this.margins != null && pngOpts.margins == null) {
          Object.assign(pngOpts, this.margins);
        }
        const pngExporter = new ImageExportUI(s);
        pngExporter.export(pngOpts);
      });
    }
  },
  render() {
    const showLabel = this.showLabel !== false;
    const allowSvg = this.allowSvgExport !== false;
    const allowPng = this.allowPngExport !== false;
    const allowJpg = this.allowJpgExport !== false;
    const buttons = [];
    if (allowSvg) {
      buttons.push(
        h3("i", {}, [
          h3(
            "a",
            {
              href: "#",
              "data-type": TYPE_SVG,
              onClick: () => this.exportSVG()
            },
            "SVG"
          )
        ])
      );
    }
    if (allowPng) {
      buttons.push(
        h3("i", {}, [
          h3(
            "a",
            {
              href: "#",
              "data-type": TYPE_PNG,
              onClick: () => this.exportPNG()
            },
            "PNG"
          )
        ])
      );
    }
    if (allowJpg) {
      buttons.push(
        h3("i", {}, [
          h3(
            "a",
            {
              href: "#",
              "data-type": TYPE_JPG,
              onClick: () => this.exportJPG()
            },
            "JPG"
          )
        ])
      );
    }
    if (showLabel) {
      buttons.unshift(h3("span", {}, [this.label]));
    }
    return h3(
      ELEMENT_DIV4,
      {
        class: `${CLASS_CONTROLS} ${CLASS_EXPORT_CONTROLS}`
      },
      buttons
    );
  }
};

