// use-visuallyjs-update.ts
import { inject as inject16, onUnmounted } from "vue";
import { EVENT_DATA_UPDATED, EVENT_GRAPH_CLEARED } from "@visuallyjs/browser-ui";
function useVisuallyJsUpdate(callback) {
  const service = inject16(VisuallyJsServiceKey);
  if (service) {
    let currentModel = null;
    const fn = () => {
      if (currentModel) {
        callback(currentModel);
      }
    };
    const cleanup = () => {
      if (currentModel) {
        currentModel.unbind(EVENT_DATA_UPDATED, fn);
        currentModel.unbind(EVENT_GRAPH_CLEARED, fn);
      }
    };
    const setup = (model) => {
      cleanup();
      currentModel = model;
      if (currentModel) {
        currentModel.bind(EVENT_DATA_UPDATED, fn);
        currentModel.bind(EVENT_GRAPH_CLEARED, fn);
        fn();
      }
    };
    service.getModel((model) => {
      setup(model);
    });
    onUnmounted(() => {
      cleanup();
    });
  }
}

